@startuml

class Bettor {
  + name : string
  + id : int
  + email : string
}

class Race {
  + raceId : int
  + startTime : datetime
}

class Runner {
  + horseName : string
  + runnerId : int
}

class Jockey {
  + name : string
  + licenseNumber : string
}

class Bet {
  + amount : double
  + odds : double
  + status : string
}

class Bookmaker {
  + name : string
  + registrationNumber : string
}

Bettor "1" -- "0..*" Bet : places
Bookmaker "1" -- "0..*" Bet : accepts
Race "1" *-- "1..*" Runner
Runner "1" *-- "1" Jockey
Race "1" -- "1" Runner : winner
Bet "0..*" -- "1" Race
Bet "0..*" -- "1" Runner

